package com.ratbag24.reminders;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.events.HitsplatApplied;

/**
 * Keeps track of how recently the player was fighting, so that reminders can
 * stay quiet while you are banking or running between tasks.
 * <p>
 * Only hitsplats count. Who the player is interacting with would also catch
 * talking to an NPC or using a bank, whereas damage dealt or taken is combat
 * and nothing else.
 */
@Singleton
public class CombatTracker
{
	/**
	 * How long after the last hit the player still counts as fighting. Long
	 * enough to cover the gap between kills and a slow weapon's attack speed.
	 */
	private static final int COMBAT_TIMEOUT_TICKS = 17;

	@Inject
	private Client client;

	private int lastCombatTick = Integer.MIN_VALUE;

	void onHitsplatApplied(HitsplatApplied event)
	{
		final boolean dealtByUs = event.getHitsplat().isMine();
		final boolean takenByUs = event.getActor() == client.getLocalPlayer();

		if (dealtByUs || takenByUs)
		{
			lastCombatTick = client.getTickCount();
		}
	}

	void reset()
	{
		lastCombatTick = Integer.MIN_VALUE;
	}

	/** Whether the player has been in combat recently enough to count. */
	public boolean isInCombat()
	{
		if (lastCombatTick == Integer.MIN_VALUE)
		{
			return false;
		}

		return client.getTickCount() - lastCombatTick <= COMBAT_TIMEOUT_TICKS;
	}
}

package com.ratbag24.reminders;

import javax.annotation.Nullable;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.plugins.Plugin;

/**
 * One thing the plugin can remind you about.
 * <p>
 * Everything here is optional bar the name, whether the reminder is switched on
 * and what it currently wants to say, so a new reminder only has to implement
 * the events it actually cares about. {@link RemindersPlugin} subscribes to the
 * client's events once and hands them to every registered reminder.
 */
public interface Reminder
{
	/** Name used in log messages and as the heading on the overlay. */
	String getName();

	/** Whether the user has this reminder switched on. */
	boolean isEnabled();

	/** Called when the plugin starts, before any events arrive. */
	default void startUp(Plugin plugin)
	{
	}

	/** Called when the plugin stops. Must leave no overlays or infoboxes behind. */
	default void shutDown()
	{
	}

	/**
	 * Called when the player logs in, hops world or logs out: anything the
	 * reminder inferred from the previous session is no longer safe to trust.
	 */
	default void reset()
	{
	}

	default void onVarbitChanged(VarbitChanged event)
	{
	}

	default void onItemContainerChanged(ItemContainerChanged event)
	{
	}

	default void onGameTick()
	{
	}

	/** Called when any of this plugin's settings changed. */
	default void onConfigChanged()
	{
	}

	/**
	 * Whether this reminder wants the player's attention right now, whatever
	 * form that attention takes.
	 * <p>
	 * Kept separate from {@link #getReminderText()} so that the visuals and the
	 * text panel can be switched on and off independently: someone who wants
	 * only a flashing screen edge should still get one.
	 */
	default boolean isNudging()
	{
		return false;
	}

	/**
	 * What to show on the reminder overlay right now, or null when this
	 * reminder has nothing to say.
	 */
	@Nullable
	default String getReminderText()
	{
		return null;
	}
}

package com.ratbag24.reminders;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.Notifier;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.Notification;

/**
 * The services every reminder needs, in one place.
 * <p>
 * Reminders are plain objects rather than injected singletons, because several
 * of them are the same class with different buffs; handing them this instead of
 * five constructor arguments each keeps them to their own business.
 */
@Singleton
public class ReminderContext
{
	@Inject
	private Client client;

	@Inject
	private Notifier notifier;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private CombatTracker combatTracker;

	@Inject
	private RemindersConfig config;

	public Client getClient()
	{
		return client;
	}

	public RemindersConfig getConfig()
	{
		return config;
	}

	/** Whether the player has dealt or taken damage recently enough to count. */
	public boolean isInCombat()
	{
		return combatTracker.isInCombat();
	}

	/**
	 * Announces something once: a notification in whatever form the user chose
	 * for it, and a chat message too when they have asked for those.
	 */
	public void announce(Notification notification, String message)
	{
		notifier.notify(notification, message);

		if (config.chatMessages())
		{
			final String formatted = new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT)
				.append(message)
				.build();

			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(formatted)
				.build());
		}
	}
}

package com.ratbag24.reminders;

import com.ratbag24.reminders.heart.TrackedHearts;
import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Notification;

/**
 * One section per reminder, each with its own Enable, so a reminder can be
 * switched off without touching the others. Section positions go up in tens to
 * leave room for the next one.
 */
@ConfigGroup(RemindersConfig.GROUP)
public interface RemindersConfig extends Config
{
	String GROUP = "aioreminders";

	// ------------------------------------------------------------------
	// General
	// ------------------------------------------------------------------

	@ConfigSection(
		name = "General",
		description = "Settings shared by every reminder.",
		position = 1
	)
	String generalSection = "generalSection";

	@ConfigItem(
		keyName = "chatMessages",
		name = "Send chat messages",
		description = "Also print a message in the game chat whenever a reminder fires.",
		section = generalSection,
		position = 1
	)
	default boolean chatMessages()
	{
		return false;
	}

	@ConfigItem(
		keyName = "screenFlash",
		name = "Flash the screen edge",
		description = "Throb a coloured glow around the edge of the game view while any"
			+ " reminder is asking for attention, and stop as soon as none is.",
		section = generalSection,
		position = 2
	)
	default boolean screenFlash()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "flashColour",
		name = "Flash colour",
		description = "The colour used for the screen edge and for highlighting an item.",
		section = generalSection,
		position = 3
	)
	default Color flashColour()
	{
		return new Color(255, 48, 48, 170);
	}

	// ------------------------------------------------------------------
	// Saturated heart
	// ------------------------------------------------------------------

	@ConfigSection(
		name = "Saturated heart",
		description = "Reminds you when your saturated or imbued heart is off cooldown.",
		position = 10
	)
	String heartSection = "heartSection";

	@ConfigItem(
		keyName = "heartEnabled",
		name = "Enable",
		description = "Track the heart cooldown and remind you when it has recharged.",
		section = heartSection,
		position = 1
	)
	default boolean heartEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "heartTrackedHearts",
		name = "Hearts to track",
		description = "The imbued and saturated hearts share one cooldown. Choose whether to"
			+ " be reminded about both, or only the saturated heart's shorter five minutes.",
		section = heartSection,
		position = 2
	)
	default TrackedHearts heartTrackedHearts()
	{
		return TrackedHearts.BOTH;
	}

	@ConfigItem(
		keyName = "heartNotification",
		name = "Notify when recharged",
		description = "Fire a notification the moment the cooldown ends.",
		section = heartSection,
		position = 3
	)
	default Notification heartNotification()
	{
		return Notification.ON;
	}

	@ConfigItem(
		keyName = "heartReminderOverlay",
		name = "Show on-screen reminder",
		description = "Keep a reminder on screen for as long as the heart is ready to use,"
			+ " rather than only announcing it once.",
		section = heartSection,
		position = 4
	)
	default boolean heartReminderOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "heartTimer",
		name = "Show cooldown timer",
		description = "Show an infobox counting down the remaining cooldown.",
		section = heartSection,
		position = 5
	)
	default boolean heartTimer()
	{
		return true;
	}

	@ConfigItem(
		keyName = "heartItemFlash",
		name = "Flash the heart in your inventory",
		description = "Throb the heart in your inventory while it is ready to invigorate,"
			+ " so the thing to click is the thing that is lit up.",
		section = heartSection,
		position = 6
	)
	default boolean heartItemFlash()
	{
		return true;
	}

	@ConfigItem(
		keyName = "heartRequireInInventory",
		name = "Only when carrying one",
		description = "Stay quiet unless a heart is actually in your inventory.",
		section = heartSection,
		position = 7
	)
	default boolean heartRequireInInventory()
	{
		return true;
	}

	@ConfigItem(
		keyName = "heartOnlyInCombat",
		name = "Only while fighting",
		description = "Stay quiet unless you have dealt or taken damage recently, so the"
			+ " reminder does not follow you around the bank.",
		section = heartSection,
		position = 8
	)
	default boolean heartOnlyInCombat()
	{
		return true;
	}

	// ------------------------------------------------------------------
	// Thrall
	// ------------------------------------------------------------------

	@ConfigSection(
		name = "Thrall",
		description = "Reminds you when your resurrected thrall has expired.",
		position = 20
	)
	String thrallSection = "thrallSection";

	@ConfigItem(
		keyName = "thrallEnabled",
		name = "Enable",
		description = "Remind you when a thrall you resurrected runs out.",
		section = thrallSection,
		position = 1
	)
	default boolean thrallEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "thrallNotification",
		name = "Notify when expired",
		description = "Fire a notification as the thrall leaves.",
		section = thrallSection,
		position = 2
	)
	default Notification thrallNotification()
	{
		return Notification.ON;
	}

	@ConfigItem(
		keyName = "thrallReminderOverlay",
		name = "Show on-screen reminder",
		description = "Keep a reminder on screen for as long as you are without a thrall.",
		section = thrallSection,
		position = 3
	)
	default boolean thrallReminderOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "thrallOnlyInCombat",
		name = "Only while fighting",
		description = "Stay quiet unless you have dealt or taken damage recently.",
		section = thrallSection,
		position = 4
	)
	default boolean thrallOnlyInCombat()
	{
		return true;
	}

	// ------------------------------------------------------------------
	// Vengeance
	// ------------------------------------------------------------------

	@ConfigSection(
		name = "Vengeance",
		description = "Reminds you when vengeance can be cast again.",
		position = 30
	)
	String vengeanceSection = "vengeanceSection";

	@ConfigItem(
		keyName = "vengeanceEnabled",
		name = "Enable",
		description = "Remind you once both the cooldown has run out and the cast you were"
			+ " holding has rebounded.",
		section = vengeanceSection,
		position = 1
	)
	default boolean vengeanceEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "vengeanceNotification",
		name = "Notify when ready",
		description = "Fire a notification as vengeance becomes castable again.",
		section = vengeanceSection,
		position = 2
	)
	default Notification vengeanceNotification()
	{
		return Notification.ON;
	}

	@ConfigItem(
		keyName = "vengeanceReminderOverlay",
		name = "Show on-screen reminder",
		description = "Keep a reminder on screen for as long as vengeance is uncast.",
		section = vengeanceSection,
		position = 3
	)
	default boolean vengeanceReminderOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "vengeanceOnlyInCombat",
		name = "Only while fighting",
		description = "Stay quiet unless you have dealt or taken damage recently. Turn this"
			+ " off if you would rather be reminded before a fight starts than during it.",
		section = vengeanceSection,
		position = 4
	)
	default boolean vengeanceOnlyInCombat()
	{
		return true;
	}

	// ------------------------------------------------------------------
	// Divine potions
	// ------------------------------------------------------------------

	@ConfigSection(
		name = "Divine potions",
		description = "Reminds you when a divine potion's boost has worn off.",
		position = 40
	)
	String divineSection = "divineSection";

	@ConfigItem(
		keyName = "divineEnabled",
		name = "Enable",
		description = "Remind you when the last of a divine potion's boosts runs out.",
		section = divineSection,
		position = 1
	)
	default boolean divineEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "divineNotification",
		name = "Notify when worn off",
		description = "Fire a notification as the boost ends.",
		section = divineSection,
		position = 2
	)
	default Notification divineNotification()
	{
		return Notification.ON;
	}

	@ConfigItem(
		keyName = "divineReminderOverlay",
		name = "Show on-screen reminder",
		description = "Keep a reminder on screen for as long as you are without the boost.",
		section = divineSection,
		position = 3
	)
	default boolean divineReminderOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "divineOnlyInCombat",
		name = "Only while fighting",
		description = "Stay quiet unless you have dealt or taken damage recently.",
		section = divineSection,
		position = 4
	)
	default boolean divineOnlyInCombat()
	{
		return true;
	}
}

package com.ratbag24.reminders;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Lists whatever the enabled reminders currently want to say. One panel is
 * shared by every reminder so that a handful of them cannot bury the screen in
 * separate boxes.
 */
class RemindersOverlay extends OverlayPanel
{
	private static final Color TITLE_COLOR = new Color(255, 199, 0);

	private final RemindersPlugin plugin;

	@Inject
	private RemindersOverlay(RemindersPlugin plugin)
	{
		super(plugin);
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final List<String> reminders = plugin.getActiveReminderTexts();

		if (reminders.isEmpty())
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Reminders")
			.color(TITLE_COLOR)
			.build());

		for (String reminder : reminders)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(reminder)
				.build());
		}

		return super.render(graphics);
	}
}

package com.ratbag24.reminders;

import com.google.inject.Provides;
import com.ratbag24.reminders.buff.BuffReminder;
import com.ratbag24.reminders.buff.BuffSettings;
import com.ratbag24.reminders.buff.Buffs;
import com.ratbag24.reminders.heart.SaturatedHeartReminder;
import com.ratbag24.reminders.visual.ItemFlashOverlay;
import com.ratbag24.reminders.visual.ScreenFlashOverlay;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * A single plugin for the small "don't forget to re-apply that" reminders, each
 * one switchable on its own.
 * <p>
 * The client's events are subscribed to once here and passed on to every
 * registered {@link Reminder}, so adding the next reminder means defining it
 * and listing it in {@link #startUp()} rather than touching the event plumbing.
 */
@PluginDescriptor(
	name = "All-in-One Reminders",
	description = "Reminds you when your saturated heart and other re-appliable buffs are ready",
	tags = {"heart", "saturated", "imbued", "thrall", "vengeance", "divine", "boost",
		"reminder", "timer", "cooldown", "buff"}
)
public class RemindersPlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private RemindersOverlay overlay;

	@Inject
	private ScreenFlashOverlay screenFlashOverlay;

	@Inject
	private ItemFlashOverlay itemFlashOverlay;

	@Inject
	private CombatTracker combatTracker;

	@Inject
	private ReminderContext reminderContext;

	@Inject
	private RemindersConfig config;

	@Inject
	private SaturatedHeartReminder saturatedHeartReminder;

	private final List<Reminder> reminders = new ArrayList<>();

	@Provides
	RemindersConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RemindersConfig.class);
	}

	@Override
	protected void startUp()
	{
		// Register each reminder here. The rest of the plugin does not care
		// which ones exist.
		//
		// The heart has a class of its own because it tracks a cooldown with a
		// countdown and two possible hearts behind one varbit. Everything else
		// so far is a buff that is simply there or not, which one class covers:
		// a new one needs a definition in Buffs, a config section, and a line
		// here.
		reminders.add(saturatedHeartReminder);

		reminders.add(new BuffReminder(reminderContext, Buffs.THRALL, new BuffSettings(
			config::thrallEnabled,
			config::thrallNotification,
			config::thrallReminderOverlay,
			config::thrallOnlyInCombat)));

		reminders.add(new BuffReminder(reminderContext, Buffs.VENGEANCE, new BuffSettings(
			config::vengeanceEnabled,
			config::vengeanceNotification,
			config::vengeanceReminderOverlay,
			config::vengeanceOnlyInCombat)));

		reminders.add(new BuffReminder(reminderContext, Buffs.DIVINE_POTION, new BuffSettings(
			config::divineEnabled,
			config::divineNotification,
			config::divineReminderOverlay,
			config::divineOnlyInCombat)));

		for (Reminder reminder : reminders)
		{
			reminder.startUp(this);
		}

		overlayManager.add(overlay);
		overlayManager.add(screenFlashOverlay);
		overlayManager.add(itemFlashOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(screenFlashOverlay);
		overlayManager.remove(itemFlashOverlay);

		for (Reminder reminder : reminders)
		{
			reminder.shutDown();
		}

		reminders.clear();
		combatTracker.reset();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final GameState state = event.getGameState();

		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING
			|| state == GameState.CONNECTION_LOST)
		{
			// Nothing inferred from the last session can be trusted, and the
			// next value read must not be mistaken for a buff running out.
			combatTracker.reset();

			for (Reminder reminder : reminders)
			{
				reminder.reset();
			}
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		for (Reminder reminder : reminders)
		{
			reminder.onVarbitChanged(event);
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		for (Reminder reminder : reminders)
		{
			reminder.onItemContainerChanged(event);
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		combatTracker.onHitsplatApplied(event);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		for (Reminder reminder : reminders)
		{
			reminder.onGameTick();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!RemindersConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		for (Reminder reminder : reminders)
		{
			reminder.onConfigChanged();
		}
	}

	/**
	 * Whether any enabled reminder is asking for attention, which is what the
	 * screen edge flash follows. Independent of the text panel, so the two can
	 * be switched on and off separately.
	 */
	public boolean isAnyReminderNudging()
	{
		for (Reminder reminder : reminders)
		{
			if (reminder.isNudging())
			{
				return true;
			}
		}

		return false;
	}

	/**
	 * What the enabled reminders want shown on screen, in registration order.
	 * Read by the overlay on the client thread while it renders.
	 */
	List<String> getActiveReminderTexts()
	{
		List<String> texts = null;

		for (Reminder reminder : reminders)
		{
			final String text = reminder.getReminderText();

			if (text != null)
			{
				if (texts == null)
				{
					texts = new ArrayList<>(reminders.size());
				}

				texts.add(text);
			}
		}

		return texts == null ? Collections.emptyList() : texts;
	}
}

package com.ratbag24.reminders.buff;

/**
 * Everything that distinguishes one buff reminder from another: what it is
 * called, what to say about it, and which varbits report it.
 * <p>
 * Keeping this as data rather than a class per buff is what makes adding the
 * next reminder a constant in {@link Buffs}, a section in the config and one
 * line of registration.
 */
public final class BuffDefinition
{
	private final String name;
	private final String notificationMessage;
	private final String reminderText;
	private final int[] varbits;

	/**
	 * @param name                 the buff's name, used for the config and logs
	 * @param notificationMessage  the one-off message sent as it runs out
	 * @param reminderText         the line shown for as long as it is missing
	 * @param varbits              every varbit that is non-zero while any part
	 *                             of the buff is still running
	 */
	public BuffDefinition(String name, String notificationMessage, String reminderText,
		int... varbits)
	{
		this.name = name;
		this.notificationMessage = notificationMessage;
		this.reminderText = reminderText;
		this.varbits = varbits.clone();
	}

	public String getName()
	{
		return name;
	}

	public String getNotificationMessage()
	{
		return notificationMessage;
	}

	public String getReminderText()
	{
		return reminderText;
	}

	public int[] getVarbits()
	{
		return varbits.clone();
	}
}

package com.ratbag24.reminders.buff;

import com.ratbag24.reminders.Reminder;
import com.ratbag24.reminders.ReminderContext;
import javax.annotation.Nullable;
import net.runelite.api.events.VarbitChanged;

/**
 * Reminds the player that a buff has run out, for any buff the game reports
 * through varbits that are non-zero while it lasts.
 * <p>
 * One instance per buff, built from a {@link BuffDefinition}. The notification
 * fires on the buff running out; the on-screen line, in contrast, reflects the
 * ongoing state of not having it, which also covers a buff never applied in the
 * first place.
 */
public class BuffReminder implements Reminder
{
	private final ReminderContext ctx;
	private final BuffDefinition definition;
	private final BuffSettings settings;
	private final BuffState state;

	public BuffReminder(ReminderContext ctx, BuffDefinition definition, BuffSettings settings)
	{
		this.ctx = ctx;
		this.definition = definition;
		this.settings = settings;
		this.state = new BuffState(definition.getVarbits());
	}

	@Override
	public String getName()
	{
		return definition.getName();
	}

	@Override
	public boolean isEnabled()
	{
		return settings.isEnabled();
	}

	@Override
	public void reset()
	{
		state.reset();
	}

	@Override
	public void onVarbitChanged(VarbitChanged event)
	{
		// The buff is tracked even while its reminder is switched off, so that
		// switching it on does not need a re-login to read right.
		final BuffState.Transition transition =
			state.onVarbitValue(event.getVarbitId(), event.getValue());

		if (transition == BuffState.Transition.EXPIRED && isEnabled() && conditionsMet())
		{
			ctx.announce(settings.getNotification(), definition.getNotificationMessage());
		}
	}

	@Override
	public void onGameTick()
	{
		if (!state.isSynced())
		{
			// Seed every watched varbit together on the first tick after
			// logging in. Adopting them this way never counts as an expiry.
			final int[] varbits = state.getVarbits();
			final int[] values = new int[varbits.length];

			for (int i = 0; i < varbits.length; i++)
			{
				values[i] = ctx.getClient().getVarbitValue(varbits[i]);
			}

			state.sync(values);
		}
	}

	@Override
	public boolean isNudging()
	{
		if (!isEnabled() || !state.isSynced() || state.isActive())
		{
			return false;
		}

		// Nothing is said to a player who has not had this buff up at all: not
		// having cast vengeance is the normal state for most of the game.
		return state.hasBeenActive() && conditionsMet();
	}

	@Nullable
	@Override
	public String getReminderText()
	{
		return isNudging() && settings.isShowReminder() ? definition.getReminderText() : null;
	}

	private boolean conditionsMet()
	{
		return !settings.isOnlyInCombat() || ctx.isInCombat();
	}
}

package com.ratbag24.reminders.buff;

import java.util.function.BooleanSupplier;
